    private static void assertOrganizationPixels(ClientGameTestContext context,Path image)throws java.io.IOException {
        var bounds=context.computeOnClient(client->{
            var row=MapCommanderPanels.selectedDivisionRows().stream().filter(m->m.organization()!=null&&m.organization()>.8).findFirst().orElse(null);if(row==null)return null;
            var hit=MapCommanderPanels.hits().stream().filter(h->h.tip().startsWith(row.name()+"\n"+row.status())).findFirst().orElseThrow();var units=MapCommanderLayout.units(client.getWindow().getGuiScaledWidth(),client.getWindow().getGuiScaledHeight());double scale=client.getWindow().getGuiScale();return new int[]{(int)Math.round((hit.x()+units.size(1.5))*scale),(int)Math.round((hit.y()+units.size(2))*scale),(int)Math.round(units.size(3)*scale),(int)Math.round((hit.h()-units.size(4))*scale)};
        });
        if(bounds==null)return;var pixels=javax.imageio.ImageIO.read(image.toFile());int green=0;for(int y=bounds[1];y<bounds[1]+bounds[3];y++)for(int x=bounds[0];x<bounds[0]+bounds[2];x++){int color=pixels.getRGB(x,y),red=color>>16&255,g=color>>8&255,blue=color&255;if(g>red+25&&g>blue+25)green++;}if(green<2)throw new AssertionError("Authoritative filled organization must render visible original green pixels inside its rotated bar: "+image);
    }
